
local wuw=[==[]==]
local rqj=
(function(...)
local ixhab={189,74,7,50,65,248,143,28,45,192,170,70,14,99,55,205,224,184,161,199,60,248,138,151,155,31,61}
local vwpj=bit32 or bit
local pqk=vwpj.bxor
for cwvwa=1,#ixhab do ixhab[cwvwa]=pqk(ixhab[cwvwa],(226*cwvwa+38)%256) end
local ig="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local dfmoa={}
for ad=1,#ig do dfmoa[ig:byte(ad)]=ad-1 end
local function ujrv(str)
  local R={} local acc,nb=0,0
  for lyo=1,#str do
    local v=dfmoa[str:byte(lyo)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function bavgv(key,data)
  local S={} for wegoh=0,255 do S[wegoh]=wegoh end
  local j=0
  for tz=0,255 do
    j=(j+S[tz]+key[(tz%#key)+1])%256
    S[tz],S[j]=S[j],S[tz]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(pqk(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=bavgv(ixhab,ujrv(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local kar=nf()
return function(big) return kar(big) end
end)(...)

return rqj(wuw)
